// Integer Conversion Rank (Compile-Time Ordering)
// Used in Integral Promotion & Usual Arithmetic Conversions

char c = 'a';
short s = 1;
int i = 2;
long L = 10L;

// 1. Integral Promotion (Types <= int usually promote to int):
// Rank(c) < Rank(i), Rank(s) < Rank(i)
decltype(c + s) promoted; // type is 'int'

// 2. Usual Arithmetic Conversion (Higher Rank Wins):
// Rank(long) > Rank(int)
decltype(i + L) rank_winner; // type is 'long'

// Hierarchy (simplified): bool < char/short < int < long < long long
